import Container from "@/components/Container";
import { pinterestKeywords } from "@/data/mockData";
import { Copy, Lightbulb } from "lucide-react";

export const metadata = {
    title: "Pinterest Keywords for Creators",
    description: "Boost your reach on Pinterest with curated keyword lists for designers and video editors.",
};

export default function KeywordsPage() {
    return (
        <div className="py-20">
            <Container>
                <header className="mb-16">
                    <h1 className="text-4xl md:text-6xl font-extrabold tracking-tighter uppercase mb-6">Pinterest Keywords</h1>
                    <p className="text-xl text-secondary max-w-2xl">
                        Strategic keywords to help you dominate Pinterest search and drive traffic to your work.
                    </p>
                </header>

                <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                    {pinterestKeywords.map((list) => (
                        <div key={list.slug} className="premium-card p-10">
                            <h2 className="text-2xl font-bold mb-6 border-b border-border pb-4 uppercase tracking-tight">
                                {list.title}
                            </h2>

                            <div className="mb-8">
                                <h3 className="text-xs font-bold uppercase tracking-widest text-secondary mb-4 flex items-center gap-2">
                                    <Copy size={14} /> Recommended Keywords
                                </h3>
                                <div className="flex flex-wrap gap-2">
                                    {list.keywords.map((kw) => (
                                        <span
                                            key={kw}
                                            className="px-3 py-1.5 bg-zinc-100 dark:bg-zinc-800 text-sm font-medium border border-border/50 hover:border-foreground transition-colors cursor-pointer"
                                        >
                                            {kw}
                                        </span>
                                    ))}
                                </div>
                            </div>

                            <div className="bg-zinc-50 dark:bg-zinc-900/50 p-6 border-l-4 border-foreground">
                                <h3 className="text-sm font-bold uppercase mb-3 flex items-center gap-2">
                                    <Lightbulb size={16} /> Pro Usage Tips
                                </h3>
                                <ul className="space-y-3">
                                    {list.tips.map((tip, idx) => (
                                        <li key={idx} className="text-sm text-secondary list-disc ml-4 italic">
                                            {tip}
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    ))}
                </div>

                {/* SEO Content Section */}
                <section className="mt-24 max-w-4xl">
                    <h2 className="text-3xl font-bold mb-6 uppercase tracking-tighter">Why Pinterest Keywords Matter?</h2>
                    <div className="prose dark:prose-invert max-w-none text-secondary space-y-4">
                        <p>
                            Pinterest is a visual search engine, not a social media platform. To get your designs and videos discovered,
                            you need to use the right language that users are searching for. Our curated lists are updated based on current trends
                            specifically within the creative niche.
                        </p>
                        <p>
                            By implementing these keywords in your Pin titles, descriptions, and alt-text, you increase the likelihood of your
                            assets being indexed and recommended to potential clients and followers.
                        </p>
                    </div>
                </section>
            </Container>
        </div>
    );
}
